// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize the contract
        address vader = address(0x1);
        address usdv = address(0x2);
        address vault = address(0x3);
        c.init(vader, usdv, vault);

        // Create a new grant proposal with any recipient and amount
        c.newGrantProposal(address(0x4), 100);

        // After newGrantProposal, the REFERENCE increments proposalCount to 1.
        // The BUG leaves proposalCount at 0 (initial).
        // Check the state variable proposalCount directly
        assertTrue(c.proposalCount() == 1, "proposalCount should be 1 after one proposal");
    }
}

