pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract with dummy addresses
        address dummy1 = address(0x1);
        address dummy2 = address(0x2);
        c.init(dummy1, dummy2, dummy1);

        // Create a new address proposal (proposal ID 1) – buggy version does NOT increment proposalCount
        c.newAddressProposal(address(0xa), "DAO");

        // Create a new grant proposal (proposal ID 2 in reference, but 1 in buggy because count stays 0)
        c.newGrantProposal(address(0xb), 100);

        // Now call cancelProposal(1, 2) – each contract may behave differently
        // For the reference, oldProposalID=1 is finalising? We need to finalise it first.
        // Actually, per the described diff, after cancelProposal completes, proposalCount differs.
        // To invoke cancelProposal, oldProposalID must be in finalising state.
        // We call voteProposal to trigger finalising for proposal 1.
        // But we need a voter with weight. Since totalWeight() from VAULT is 0, we simulate by calling voteProposal
        // which will set mapPID_finalising if conditions met.
        // For simplicity, we directly call finaliseProposal after ensuring conditions? No – we need to reach cancel.
        // Instead, we call voteProposal to trigger _finalise (since hasQuorum with totalWeight=0? hasQuorum: 0 > 0 is false, so no finalise).
        // So we need to set up VAULT to return non-zero totalWeight and member weight.
        // We'll skip that complexity: the expected diff is on proposalCount after cancelProposal executes.
        // According to the mutant, proposalCount stays 0 after newAddressProposal, so after newGrantProposal it becomes 1 (correct becomes 2).
        // So we can just read proposalCount after both proposals.
        uint256 countAfter = c.proposalCount();
        assertTrue(countAfter == 2, "Reference should have 2 proposals");
    }
}

