pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up addresses
        address vader = address(0x1234);
        address usdv = address(0x5678);
        address vault = address(0x9ABC);
        address member = address(0xDEAD);
        address recipient = address(0xBEEF);

        // Initialize with a non-zero VADER
        c.init(vader, usdv, vault);

        // We need the vault to have totalWeight > 0 so that votes can achieve quorum/majority
        // But we can't directly set vault state; instead we rely on the fact that 
        // the test will call cancelProposal which only requires mapPID_finalising[oldProposalID] == true.
        // To make a proposal finalising, we need a proposal and vote to trigger _finalise.
        // Or simpler: create two proposals and vote on first to trigger finalising, then cancel it.

        // Create a grant proposal (ID 1)
        c.newGrantProposal(recipient, 100);

        // Create another proposal of same type (need same type for cancelProposal)
        c.newGrantProposal(recipient, 200);

        // Vote on proposal 1 to trigger finalising (need totalWeight > 0 from vault to get majority/quorum)
        // Since we can't set vault weights, we'll use prank as member
        vm.prank(member);
        c.voteProposal(1);

        // Now proposal 1 should be finalising
        vm.prank(member);
        c.cancelProposal(1, 2);

        // Assert that VADER is non-zero (reference has vader, mutant has address(0))
        assertTrue(c.VADER() != address(0), "VADER should be non-zero");
    }
}

